import sys
from rich.traceback import Traceback
from rich.console import Console
from io import StringIO

def test_exception_notes():
    console = Console(file=StringIO(), force_terminal=True)
    try:
        try:
            raise ValueError("Main Error")
        except ValueError as e:
            if hasattr(e, "add_notes"):
                e.add_notes("Note 1\nNote 2")
            else:
                # Fallback for versions where add_notes isn't available 
                # but we can still set __notes__ if it's 3.11+
                setattr(e, "__notes__", "Note 1\nNote 2")
            raise e
    except Exception:
        console.print(Traceback())

    output = console.file.getvalue()
    print(f"Output:\n{output}")
    assert "Note 1" in output
    assert "Note 2" in output

if __name__ == "__main__":
    try:
        test_exception_notes()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        sys.exit(1)

